# -------------------------------------------------------------------------
# 🗄️ LOCAL SQLITE DATABASE ARCHITECTURE
# -------------------------------------------------------------------------
DB_FILE = "mme_enterprise.db"

def init_db():
    conn = sqlite3.connect(DB_FILE)
    cursor = conn.cursor()
    cursor.execute("""
        CREATE TABLE IF NOT EXISTS customers (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            name TEXT UNIQUE NOT NULL,
            phone TEXT,
            gstin TEXT,
            billing_address TEXT,
            site_address TEXT
        )
    """)
    conn.commit()
    conn.close()

def save_customer_to_db(name, phone, gstin, billing_address, site_address):
    if not name.strip():
        return False
    try:
        conn = sqlite3.connect(DB_FILE)
        cursor = conn.cursor()
        cursor.execute("""
            INSERT INTO customers (name, phone, gstin, billing_address, site_address)
            VALUES (?, ?, ?, ?, ?)
            ON CONFLICT(name) DO UPDATE SET
                phone=excluded.phone,
                gstin=excluded.gstin,
                billing_address=excluded.billing_address,
                site_address=excluded.site_address
        """, (name.strip(), phone.strip(), gstin.strip(), billing_address.strip(), site_address.strip()))
        conn.commit()
        conn.close()
        return True
    except:
        return False

def fetch_all_customers():
    conn = sqlite3.connect(DB_FILE)
    df = pd.read_sql_query("SELECT * FROM customers ORDER BY name ASC", conn)
    conn.close()
    return df

init_db()

