def send_carrier_sms(api_key, mobile_number, message_body):
    url = "https://www.fast2sms.com/dev/bulkV2"
    payload = {"route": "q", "message": message_body, "language": "english", "numbers": str(mobile_number)}
    headers = {'authorization': api_key, 'Content-Type': "application/x-www-form-urlencoded", 'Cache-Control': "no-cache"}
    try:
        response = requests.post(url, data=payload, headers=headers)
        return response.json().get("return") == True
    except:
        return False

def send_invoice_email(sender_email, app_password, receiver_email, invoice_no, customer_name, total_amt, pdf_bytes, is_gst):
    doc_type = "Tax Invoice" if is_gst else "Bill Estimate"
    try:
        msg = MIMEMultipart()
        msg['From'] = sender_email
        msg['To'] = receiver_email
        msg['Subject'] = f"New {doc_type} Generated: {invoice_no} - {customer_name}"
        body = f"Greetings,\n\nA new {doc_type.lower()} has been generated.\nNumber: {invoice_no}\nTotal: Rs. {total_amt:.2f}"
        msg.attach(MIMEText(body, 'plain'))
        part = MIMEBase('application', 'octet-stream')
        part.set_payload(pdf_bytes)
        encoders.encode_base64(part)
        part.add_header('Content-Disposition', f"attachment; filename={invoice_no.replace('/', '_')}.pdf")
        msg.attach(part)
        server = smtplib.SMTP('smtp.gmail.com', 587)
        server.starttls()
        server.login(sender_email, app_password)
        server.sendmail(sender_email, receiver_email, msg.as_string())
        server.quit()
        return True
    except:
        return False

