def generate_pdf(metadata, customer, items_list, logo_bytes, sign_bytes, is_gst):
    buffer = io.BytesIO()
    doc = SimpleDocTemplate(buffer, pagesize=letter, rightMargin=36, leftMargin=36, topMargin=50, bottomMargin=45)
    story = []
    styles = getSampleStyleSheet()
    cell_style = ParagraphStyle('CellStyle', parent=styles['Normal'], fontSize=9, leading=11)
    cell_right = ParagraphStyle('CellRight', parent=styles['Normal'], fontSize=9, leading=11, alignment=2)
    cell_bold_right = ParagraphStyle('CellBoldRight', parent=styles['Normal'], fontSize=9, leading=11, fontName="Helvetica-Bold", alignment=2)

    # 🏛️ REPAIRED INTEGRATED CANVAS CALLBACK ENGINE
    def draw_invoice_page_decorations(canvas_obj, doc_obj):
        canvas_obj.saveState()
        
        # 1. Geometry Geometric Framing Bars
        canvas_obj.setFillColor(colors.HexColor('#1A365D'))
        canvas_obj.rect(0, 772, 612, 20, fill=True, stroke=False)
        canvas_obj.setFillColor(colors.HexColor('#E53E3E'))
        canvas_obj.rect(0, 766, 612, 6, fill=True, stroke=False)
        canvas_obj.setFillColor(colors.HexColor('#E2E8F0'))
        canvas_obj.rect(18, 36, 3, 710, fill=True, stroke=False)
        canvas_obj.setFillColor(colors.HexColor('#1A365D'))
        canvas_obj.rect(36, 36, 540, 2, fill=True, stroke=False)
        
        # 2. 🎯 FORCED BACKGROUND IMAGE WATERMARK HOOK
        if logo_bytes:
            canvas_obj.setFillAlpha(0.07)   # Crisp 7% background tint opacity
            canvas_obj.setStrokeAlpha(0.07)
            
            w_width = 260
            w_height = 120
            x_pos = (612 - w_width) / 2
            y_pos = (792 - w_height) / 2
            
            try:
                # Wrap bytes cleanly into a completely independent image reader instance
                pil_img = PILImage.open(io.BytesIO(logo_bytes))
                canvas_obj.drawImage(pil_img, x_pos, y_pos, width=w_width, height=w_height, mask='auto')
            except:
                pass
                
        canvas_obj.restoreState()

    header_data = []
    if logo_bytes:
        logo_img = Image(io.BytesIO(logo_bytes), width=FIXED_LOGO_WIDTH, height=FIXED_LOGO_HEIGHT)
        logo_img.hAlign = 'LEFT'
    else:
        logo_img = Paragraph("<b>[ MME LOGO ]</b>", cell_style)
        
    gst_line = f"<b>GSTIN:</b> {LOCKED_SELLER_GSTIN}<br/>" if is_gst else ""
    company_text = f"""
    <font size=15 color="#1A365D"><b>{SELLER_NAME}</b></font><br/>
    <font size=9 color="#5A67D8"><b>A Venture of {PARENT_COMPANY}</b></font><br/>
    <font size=8.5 color="#E53E3E"><b><i>“{TAGLINE}”</i></b></font><br/>
    <font size=9 color="#4A5568">{SELLER_ADDRESS}<br/>
    {gst_line}<b>Email:</b> {metadata['seller_email']}</font>
    """
    company_p = Paragraph(company_text, cell_style)
    header_data.append([logo_img, company_p])
    
    header_table = Table(header_data, colWidths=[135, 405])
    header_table.setStyle(TableStyle([
        ('VALIGN', (0,0), (-1,-1), 'TOP'), ('LEFTPADDING', (1,0), (1,0), 15), ('BOTTOMPADDING', (0,0), (-1,-1), 10),
    ]))
    story.append(header_table)
    story.append(Spacer(1, 10))
    
    title_label = "TAX INVOICE" if is_gst else "BILL ESTIMATE"
    meta_text = f"""
    <font size=12 color="#1A365D"><b>{title_label}</b></font><br/><br/>
    <b>Number:</b> {metadata['inv_no']}<br/>
    <b>Date:</b> {metadata['date'].strftime('%d-%b-%Y')}<br/>
    <b>Place:</b> {metadata['place_of_supply']}
    """
    cust_phone_str = customer['phone'] if customer['phone'] else "N/A"
    gst_cust_part = f"<b>GSTIN:</b> {customer['gstin']}<br/>" if is_gst and customer['gstin'] else ""
    cust_text = f"""
    <b>BILLED TO:</b><br/>
    <font size=10 color="#1A365D"><b>{customer['name']}</b></font><br/>
    {customer['address']}<br/>
    {gst_cust_part}<b>Contact Mob:</b> {cust_phone_str}<br/>
    <b>Site Address:</b> {customer['site_address']}
    """
    
    panel_data = [[Paragraph(meta_text, cell_style), Paragraph(cust_text, cell_style)]]
    panel_table = Table(panel_data, colWidths=[200, 340])
    panel_table.setStyle(TableStyle([
        ('BACKGROUND', (0,0), (-1,-1), colors.HexColor('#F8FAFC')), 
        ('BOX', (0,0), (-1,-1), 1, colors.HexColor('#CBD5E0')),
        ('LINELEFT', (0,0), (0,-1), 3, colors.HexColor('#1A365D')), 
        ('PADDING', (0,0), (-1,-1), 12), 
        ('VALIGN', (0,0), (-1,-1), 'TOP'),
    ]))
    story.append(panel_table)
    story.append(Spacer(1, 15))
    
    if is_gst:
        table_headers = [
            Paragraph("<b>Sl.</b>", cell_style), Paragraph("<b>Description</b>", cell_style), Paragraph("<b>HSN</b>", cell_style),
            Paragraph("<b>Qty</b>", cell_right), Paragraph("<b>Rate (Rs.)</b>", cell_right), Paragraph("<b>Taxable</b>", cell_right),
            Paragraph("<b>CGST</b>", cell_right), Paragraph("<b>SGST</b>", cell_right), Paragraph("<b>Total (Rs.)</b>", cell_right)
        ]
        col_widths = [25, 165, 50, 45, 45, 55, 50, 50, 55]
    else:
        table_headers = [
            Paragraph("<b>Sl.</b>", cell_style), Paragraph("<b>Description</b>", cell_style),
            Paragraph("<b>Qty</b>", cell_right), Paragraph("<b>Unit</b>", cell_right), Paragraph("<b>Rate (Rs.)</b>", cell_right),
            Paragraph("<b>Total (Rs.)</b>", cell_right)
        ]
        col_widths = [30, 270, 50, 50, 70, 70]
        
    table_rows = [table_headers]
    total_taxable, total_cgst, total_sgst, total_grand = 0.0, 0.0, 0.0, 0.0
    
    for idx, item in enumerate(items_list):
        amount_val = item['qty'] * item['rate']
        if is_gst:
            cgst = amount_val * 0.09
            sgst = amount_val * 0.09
            row_total = amount_val + cgst + sgst
            total_cgst += cgst; total_sgst += sgst; total_taxable += amount_val; total_grand += row_total
            table_rows.append([
                Paragraph(str(idx + 1), cell_style), Paragraph(item['desc'], cell_style), Paragraph(item['hsn'], cell_style),
                Paragraph(f"{item['qty']:.1f} {item['unit']}", cell_right), Paragraph(f"{item['rate']:.2f}", cell_right),
                Paragraph(f"{amount_val:.2f}", cell_right), Paragraph(f"{cgst:.2f}", cell_right), Paragraph(f"{sgst:.2f}", cell_right),
                Paragraph(f"{row_total:.2f}", cell_right)
            ])
        else:
            total_grand += amount_val
            table_rows.append([
                Paragraph(str(idx + 1), cell_style), Paragraph(item['desc'], cell_style),
                Paragraph(f"{item['qty']:.1f}", cell_right), Paragraph(item['unit'] if item['unit'] else 'Qty', cell_right),
                Paragraph(f"{item['rate']:.2f}", cell_right), Paragraph(f"{amount_val:.2f}", cell_right)
            ])
            
    if is_gst:
        table_rows.append([
            Paragraph("<b>Grand Total</b>", cell_style), "", "", "", "",
            Paragraph(f"<b>{total_taxable:.2f}</b>", cell_bold_right), Paragraph(f"<b>{total_cgst:.2f}</b>", cell_bold_right),
            Paragraph(f"<b>{total_sgst:.2f}</b>", cell_bold_right), Paragraph(f"<b>{total_grand:.2f}</b>", cell_bold_right)
        ])
    else:
        table_rows.append([
            Paragraph("<b>Grand Total Amount</b>", cell_style), "", "", "", "", Paragraph(f"<b>Rs. {total_grand:.2f}</b>", cell_bold_right)
        ])
        
    item_table = Table(table_rows, colWidths=col_widths)
    t_style = [
        ('BACKGROUND', (0,0), (-1,0), colors.HexColor('#1A365D')), 
        ('TEXTCOLOR', (0,0), (-1,0), colors.whitesmoke),
        ('ALIGN', (0,0), (-1,0), 'CENTER'), 
        ('BOTTOMPADDING', (0,0), (-1,0), 6), 
        ('GRID', (0,0), (-1,-1), 0.5, colors.HexColor('#E2E8F0')),
        ('SPAN', (0,-1), (4,-1)), 
        ('BACKGROUND', (0,-1), (-1,-1), colors.HexColor('#EDF2F7')), 
        ('VALIGN', (0,0), (-1,-1), 'MIDDLE'),
    ]
    
    for row_i in range(1, len(table_rows) - 1):
        if row_i % 2 == 0:
            t_style.append(('BACKGROUND', (0, row_i), (-1, row_i), colors.HexColor('#F8FAFC')))
            
    item_table.setStyle(TableStyle(t_style))
    story.append(item_table)
    story.append(Spacer(1, 20))
    
    bank_text = f"""
    <b>Payment Remittance Details:</b><br/>
    <b>Bank Name:</b> {LOCKED_BANK_NAME}<br/>
    <b>Beneficiary:</b> {BANK_BENEFICIARY}<br/>
    <b>Account No:</b> {LOCKED_BANK_AC}<br/>
    <b>IFSC Code:</b> {LOCKED_BANK_IFSC}<br/>
    <b>UPI ID:</b> {BANK_UPI}<br/>
    """
    if sign_bytes:
        sign_img = Image(io.BytesIO(sign_bytes), width=120, height=50)
        sign_img.hAlign = 'RIGHT'
        sign_block = [sign_img, Paragraph("<font size=8 color='#4A5568'>Authorized Signatory<br/>Digitally Authenticated</font>", cell_right)]
    else:
        sign_block = [Spacer(1, 45), Paragraph("<b>For Maa Manikeswari Earthmovers</b><br/><font size=8 color='#718096'>Authorized Signatory</font>", cell_right)]
        
    footer_data = [[Paragraph(bank_text, cell_style), sign_block]]
    footer_table = Table(footer_data, colWidths=[300, 240])
    footer_table.setStyle(TableStyle([('VALIGN', (0,0), (-1,-1), 'BOTTOM'), ('ALIGN', (1,0), (1,0), 'RIGHT')]))
    story.append(KeepTogether(footer_table))
    
    # 💡 Fire decoration callback cleanly across the document instance build stream directly
    doc.build(story, onFirstPage=draw_invoice_page_decorations, onLaterPages=draw_invoice_page_decorations)
    buffer.seek(0)
    return buffer.getvalue(), total_grand

